75: async function fetchWithRetry(url) {
76:     let lastError
77:     for (let attempt = 1; attempt <= 3; attempt++) {
78:         try {
79:             const response = await fetch(url, { signal: AbortSignal.timeout(30_000) })
80:             if (response.ok) return response
81:             lastError = new Error(`${response.status} ${response.statusText}`)
82:             if (response.status < 500) break
83:         } catch (error) {
84:             lastError = error instanceof Error ? error : new Error(String(error))
85:         }
86:         if (attempt < 3) await new Promise(resolve => setTimeout(resolve, attempt * 1000))
87:     }
88:     throw new Error(`failed to download ${url}: ${lastError?.message ?? lastError}`)
89: }
