397: async function generateMonacoMaps() {
398:     const packs = PACKS.filter(pack => !only || pack.output === only);
399:     if (!packs.length) return;
400:     const monacoRoot = [
401:         path.join(webRoot, 'node_modules/monaco-editor'),
402:         path.join(frontendRoot, 'node_modules/monaco-editor'),
403:     ].find(candidate => fs.existsSync(candidate));
404:     if (!monacoRoot) {
405:         fail('monaco-editor is not installed; run npm ci in calcpad-web first');
406:         return;
407:     }
408:     const esmRoot = path.join(monacoRoot, 'esm');
409:     const calls = scanMonacoCalls(esmRoot);
410:     console.log(`Monaco NLS maps from vscode-loc ${VSCODE_LOC_TAG} (${VSCODE_LOC_COMMIT.slice(0, 12)})`);
411:     console.log(`Monaco: ${monacoRoot}`);
412:     console.log(`Calls: ${calls.length} across ${new Set(calls.map(call => call.module)).size} modules\n`);
413:     if (!check) fs.mkdirSync(monacoDir, { recursive: true });
414: 
415:     for (const pack of packs) {
416:         let contents;
417:         try {
418:             contents = await loadFullPack({ pack: pack.folder, locCommit: VSCODE_LOC_COMMIT });
419:         } catch (error) {
420:             fail(`${pack.output}: ${error.message}`);
421:             continue;
422:         }
423:         const map = {};
424:         const conflicts = new Set();
425:         const placeholderMismatches = new Set();
426:         const misses = [];
427:         let hits = 0;
428:         let identical = 0;
429:         for (const call of calls) {
430:             const translation = contents[call.module]?.[call.key];
431:             if (typeof translation !== 'string' || !translation) {
432:                 misses.push(call);
433:                 continue;
434:             }
435:             if (translation === call.english) {
436:                 identical++;
437:                 continue;
438:             }
439:             if (placeholders(translation) !== placeholders(call.english)) {
440:                 placeholderMismatches.add(`${call.module}::${call.key}`);
441:                 continue;
442:             }
443:             if (addTranslation(map, call.module, call.key, translation, conflicts)) hits++;
444:         }
445:         const sorted = sortMap(map);
446:         const entries = Object.values(sorted).reduce((sum, module) => sum + Object.keys(module).length, 0);
447:         const coverage = ((hits / calls.length) * 100).toFixed(1);
448:         console.log(
449:             `${pack.output}: ${hits} translated, ${identical} identical to English, ${misses.length} missing ` +
450:             `(${coverage}% translated, ${entries} entries)`,
451:         );
452:         if (conflicts.size)
453:             console.warn(`  conflicting translations: ${[...conflicts].slice(0, 5).join(', ')}${conflicts.size > 5 ? '…' : ''}`);
454:         if (placeholderMismatches.size)
455:             console.warn(`  placeholder mismatches: ${[...placeholderMismatches].slice(0, 5).join(', ')}${placeholderMismatches.size > 5 ? '…' : ''}`);
456:         const byModule = new Map();
457:         for (const miss of misses) byModule.set(miss.module, (byModule.get(miss.module) ?? 0) + 1);
458:         const top = [...byModule].sort((a, b) => b[1] - a[1]).slice(0, 5);
459:         if (top.length) console.log(`  top misses: ${top.map(([module, count]) => `${module} (${count})`).join(', ')}`);
460:         if (verbose) {
461:             for (const miss of misses) console.log(`  ${miss.module} :: ${miss.key} :: ${miss.english}`);
462:         }
463: 
464:         const serialized = JSON.stringify(sorted, null, 2) + '\n';
465:         const target = path.join(monacoDir, `${pack.output}.json`);
466:         if (check) {
467:             const current = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : '';
468:             if (current !== serialized) fail(`  out of date: ${path.relative(frontendRoot, target)}`);
469:         } else {
470:             fs.writeFileSync(target, serialized);
471:             console.log(`  wrote ${path.relative(frontendRoot, target)}`);
472:         }
473:     }
474: }
