505:         .map(label => ({
506:             label,
507:             file: `${label}.ts`,
508:             manifest: readJsonSafe(path.join(messagesDir, `provenance.${label}.json`)),
509:         }));
510:     for (const catalog of catalogs) {
511:         if (catalog.manifest.default)
512:             errors.push(`provenance.${catalog.label}.json: a default source is not allowed`);
513:     }
514:     const catalogResults = [];
515:     for (const catalog of catalogs) {
516:         const keys = parseKeys(catalog.file);
