    'editor.formattingHotkeys': extra('Formatting Hotkeys', 'formattingHotkeys', 'updateFormattingHotkeys', true),
    'editor.previewCursorSync': extra('Sync Preview to Cursor Line', 'previewCursorSync', 'updatePreviewCursorSync', false),
    'editor.autoRun': extra('Auto-Run Preview', 'autoRun', 'updateAutoRun', true),
